settle <- function(cf_path_time, coupon_dates, T_s, conventions) {
  # cf_path_time: [n_paths x n_months] matrix from the projection stage
  # Returns: list with NPV, AI, dirty, clean per path

  last_coupon <- max(coupon_dates[coupon_dates <= T_s])
  next_coupon <- min(coupon_dates[coupon_dates >  T_s])
  d_accr      <- as.numeric(T_s - last_coupon)
  d_basis     <- ifelse(conventions$dcb == "30/360", 360,
                 ifelse(conventions$dcb == "ACT/360", 360, 365))

  AI <- B_factor * coupon * d_accr / d_basis

  # Drop the leading month if settlement crosses the coupon date (cum/ex)
  # Adjust the first-period cashflow for partial accrual
  ...

  # Discount remaining cashflows from T_s to each payment date
  disc <- exp(-cumsum(rate_path_to_pay_date * dt))
  NPV <- rowSums(cf_path_time * disc)

  list(NPV = NPV, AI = AI, dirty = 100 * NPV / B_factor,
       clean = 100 * (NPV - AI) / B_factor)
}


## ---- 02: Accrued Interest  (qmd line 211) --------------------------------------------

accrued_interest <- function(B_factor, coupon, T_settle, T_last_coupon,
                              basis = "ACT/360") {
  d_accr <- as.numeric(T_settle - T_last_coupon)
  factor <- switch(basis,
                   "30/360"  = pmin(d_accr, 30) / 360,
                   "ACT/360" = d_accr / 360,
                   "ACT/365" = d_accr / 365)
  B_factor * coupon * factor
}

# Example
accrued_interest(B_factor = 10e6, coupon = 0.0825,
                 T_settle = as.Date("2026-05-10"),
                 T_last_coupon = as.Date("2026-04-25"))


## ---- 03: Clean / Dirty Price Conversion  (qmd line 230) ------------------------------

quote_prices <- function(NPV, AI, par_balance) {
  list(
    dirty = 100 * NPV / par_balance,
    clean = 100 * (NPV - AI) / par_balance,
    accrued_pct = 100 * AI / par_balance
  )
}


## ---- 04: Settlement Logic  (qmd line 242) --------------------------------------------

library(oasr)

settle <- function(cf_path_time, coupon_dates, T_s, conventions) {
  last_coupon <- max(coupon_dates[coupon_dates <= T_s])
  next_coupon <- min(coupon_dates[coupon_dates >  T_s])
  d_accr <- as.numeric(T_s - last_coupon)

  AI <- conventions$B_factor * conventions$coupon *
        d_accr / conventions$dcb_denom

  # Drop ex-coupon month if applicable
  if (T_s > conventions$record_date && T_s < next_coupon) {
    cf_path_time[, 1] <- 0
  }

  # Discount remaining cashflows from T_s
  disc <- exp(-cumsum(conventions$rate_to_pay_dates))
  NPV  <- rowSums(cf_path_time * disc)
  list(NPV = NPV, AI = AI,
       dirty = 100 * NPV / conventions$B_factor,
       clean = 100 * (NPV - AI) / conventions$B_factor)
}


## ---- 05: Holiday Roll Convention  (qmd line 269) -------------------------------------

library(bizdays)

create.calendar("UnitedStates/NYSE", weekdays = c("saturday","sunday"))

next_business_day <- function(d) {
  if (is.bizday(d, "UnitedStates/NYSE")) d
  else add.bizdays(d, 1, "UnitedStates/NYSE")
}

# Roll a Sunday payment to Monday
next_business_day(as.Date("2026-04-26"))   # Sunday -> Monday


## ---- 06: T+N Cycle Settlement Date  (qmd line 285) -----------------------------------

trade_to_settle <- function(trade_date, T_plus = 2) {
  add.bizdays(trade_date, T_plus, "UnitedStates/NYSE")
}


## ---- 07: Day-Count Comparison  (qmd line 293) ----------------------------------------

basis_compare <- function(start, end) {
  d <- as.numeric(end - start)
  data.frame(
    `30/360`  = pmin(d, 30) / 360,
    `ACT/360` = d / 360,
    `ACT/365` = d / 365
  )
}

basis_compare(as.Date("2026-04-25"), as.Date("2026-05-25"))


